+  'FULL JOIN',
+  'INNER JOIN',
+  'CROSS JOIN',
+  'AS',
+]);
+
+function detectPipeClauses(tokens: Token[]): Token[] {
+  let expectingClause = true;
+  let inAggregate = false;
+
+  return tokens.map(token => {
+    if (token.type === TokenType.PIPE_OPERATOR) {
+      expectingClause = true;
+      inAggregate = false;
+      return token;
+    }
+    if (expectingClause && pipeClauses.has(token.text)) {
+      expectingClause = false;
+      inAggregate = token.text === 'AGGREGATE';
+      return { ...token, type: TokenType.PIPE_CLAUSE };
+    }
+    if (inAggregate && token.text === 'GROUP BY') {
+      return { ...token, type: TokenType.PIPE_GROUP_BY };
+    }
+    return token;
+  });
+}
